export const SNAKE_SPECIES_BY_ID = Object.fromEntries(INITIAL_SNAKE_SPECIES.map((species) => [species.id, species])) as Record<string, SnakeSpeciesRecord>;

export function searchSnakeSpecies(query: string): SnakeSpeciesRecord[] { const normalized = query.trim().toLowerCase(); if (!normalized) return INITIAL_SNAKE_SPECIES; return INITIAL_SNAKE_SPECIES.filter((species) => [species.acceptedScientificName, ...species.commonNames, ...species.searchAliases, ...(species.synonyms ?? [])].some((value) => value.toLowerCase().includes(normalized))); }

export function findSnakeSpecies(value: string | null | undefined): SnakeSpeciesRecord | undefined {
  const normalized = value?.trim().toLowerCase();
  if (!normalized) return undefined;
  return INITIAL_SNAKE_SPECIES.find((species) => [species.id, species.acceptedScientificName, ...species.commonNames, ...species.searchAliases, ...(species.synonyms ?? [])].some((candidate) => candidate.toLowerCase() === normalized))
    ?? INITIAL_SNAKE_SPECIES.find((species) => [species.acceptedScientificName, ...species.commonNames, ...species.searchAliases, ...(species.synonyms ?? [])].some((candidate) => candidate.toLowerCase().includes(normalized) || normalized.includes(candidate.toLowerCase())));
}
